%[text] ## Physical Problem: Membrane Deflection BVP
%[text] A string under distributed load satisfies: $ \\frac{d^2 u}{dx^2} +  \\frac{d^2 u}{dy^2}= 1 $ on $ \[0,1\] $ with $ u(0) = 0 $ and $ u(1) = 0 $ (fixed ends). Here $ u(x) $ is deflection and we have a constant unit load $ f(x) = 1 $.
N = 20;
M = 5;
x = linspace(0,2,N);
y = linspace(0,1,M);
dx = x(2)-x(1) %[output:06eefa27]
dy = y(2)-y(1) %[output:04bac19a]

Map = zeros(N,M);
Counter = 1;
figure(Position=[0,0,800,600]) %[output:05545a91]
for ix = 1:N
    for iy = 1:M
        Map(ix,iy) = Counter;
        scatter(x(ix),y(iy),200,SeriesIndex=1) %[output:05545a91]
        hold on
        text(x(ix),y(iy),string(Map(ix,iy)),VerticalAlignment="middle",HorizontalAlignment="center")
        Counter = Counter + 1;
    end
end
axis off %[output:05545a91]
axis equal %[output:05545a91]

